@Service
public class BloodUnitService {
    checkIn(barcode, componentType, expireDate):
        expireAt = expireDate.atTime(23,59,59).toInstant(ZoneOffset.UTC)
        try insert catch DuplicateKeyException -> 409
    applyTestResult(barcode, testType, outcome):
        unit = repo.findByBarcodeForUpdate or throw 404
        if unit.status().isTerminal():
            lateEventRepo.insert(...); return ack(unit.status, late=true)
        initial = testType==INITIAL ? outcome : unit.initialResult()
        recheck = testType==RECHECK ? outcome : unit.recheckResult()
        status = decide(initial, recheck)
        repo.updateResultsAndStatus(...)
        return ack(status, late=false)
    static decide: if either UNQUALIFIED -> DISCARDED; both QUALIFIED -> RELEASABLE; one QUALIFIED -> ISOLATED; else PENDING
}
```

