```java
@Transactional
public ReleaseResult release(String requestId, String barcode, Instant windowStart, Instant windowEnd) {
    String fp = fingerprint(requestId, barcode, windowStart, windowEnd);
    var existing = releaseRepo.findByRequestId(requestId);
    if (existing.isPresent()) {
        var log = existing.get();
        if (!log.fingerprint().equals(fp)) throw new ApiException(CONFLICT, "同键异参...");
        return new ReleaseResult(requestId, log.outcome(), log.unitStatus(), log.message(), true);
    }
    BloodUnit unit = unitRepo.findByBarcodeForUpdate(barcode).orElseThrow(404);
    Instant now = clock.instant();
    String outcome; UnitStatus status; String message;
    if (now.isAfter(unit.expireAt())) {
        unitRepo.markExpiredDiscarded(barcode, now);
        outcome="REJECTED"; status=EXPIRED_DISCARDED; message="单位已过效期，标记过期报废";
    } else if (unit.status() == RELEASABLE) {
        int updated = unitRepo.compareAndSetStatus(barcode, RELEASABLE, RELEASED, now);
        if (updated == 1) {
            issueRepo.insert(requestId, barcode, windowStart, windowEnd, now);
            outcome="RELEASED"; status=RELEASED; message=null;
        } else {
            // 并发下库存已被扣减，重读真实状态
            status = unitRepo.findByBarcode(barcode).get().status();
            outcome="REJECTED"; message="可发库存不足";
        }
    } else {
        outcome="REJECTED"; status=unit.status(); message="当前状态不可放行: "+status;
    }
    var log = new ReleaseRequestLog(requestId, fp, barcode, outcome, status, message, now);
    try { releaseRepo.insert(log); }
    catch (DuplicateKeyException e) {
        // 并发同键：重读并按指纹判定
        var raced = releaseRepo.findByRequestId(requestId).orElseThrow();
