import com.example.starter.blood.service.ReleaseResult;
import com.example.starter.blood.service.ReleaseService;

/**
 * 放行接口：requestId 幂等，放行成功原子扣减库存并生成发血记录。
 */
@RestController
@RequestMapping("/api/releases")
public class ReleaseController {

    private final ReleaseService releaseService;

    public ReleaseController(ReleaseService releaseService) {
        this.releaseService = releaseService;
    }

    /**
     * 提交放行请求。同键同参返回首次结果；同键异参返回 409；
     * 业务拒绝（状态不可放行/已过期）返回 200 且携带单位当前真实状态。
     *
     * @param request 放行请求
     * @return 放行处理结果
     */
    @PostMapping
    public ReleaseResult release(@Valid @RequestBody ReleaseRequestBody request) {
        return releaseService.release(request.requestId(), request.barcode(), request.windowStart(),
                request.windowEnd());
    }
}

package com.example.starter.blood.web;

import java.util.Map;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.http.converter.HttpMessageNotReadableException;

import com.example.starter.blood.service.ApiException;

/**
 * 全局异常处理：业务异常按携带状态码返回，参数校验失败返回 400。
 */
@RestControllerAdvice
public class ApiExceptionHandler {

    /**
     * 业务异常（404 条码不存在 / 409 幂等冲突等）。
     *
     * @param e 业务异常
     * @return 错误响应
     */
    @ExceptionHandler(ApiException.class)
    public ResponseEntity<Map<String, String>> handleApi(ApiException e) {
        return ResponseEntity.status(e.status()).body(Map.of("error", e.getMessage()));
    }

    /**
     * 请求体校验失败。
     *
     * @param e 校验异常
     * @return 400 错误响应
     */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Map<String, String>> handleValidation(MethodArgumentNotValidException e) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("error", "请求参数校验失败"));
    }

    /**
     * 请求体无法解析（如枚举值非法）。
     *
     * @param e 解析异常
     * @return 400 错误响应
     */
    @ExceptionHandler(HttpMessageNotReadableException.class)
    public ResponseEntity<Map<String, String>> handleUnreadable(HttpMessageNotReadableException e) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("error", "请求体无法解析"));
    }
}

